  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  border: none;
  border-radius: var(--radius-md);
  background: var(--color-button-primary-bg);
  color: var(--color-button-primary-fg);
  font-family: var(--typo-label-md-fontFamily);
  font-size: var(--typo-label-md-fontSize);
  font-weight: var(--typo-label-md-fontWeight);
  line-height: var(--typo-label-md-lineHeight);
}

.button[data-variant="variant=secondary,size=md"] {
  background: var(--color-button-secondary-bg);
  color: var(--color-button-secondary-fg);
}
```

```html
<button class="button" data-variant="variant=primary,size=md">
  <span class="button__label">Button</span>
</button>
<button class="button" data-variant="variant=secondary,size=md">
  <span class="button__label">Button</span>
</button>
```
